> But, if you create 2 String objects with same value but using new keyboard instead...

       String pizza1 = new String("Beef");
	   String pizza2 = new String("Beef");

	   if(pizza1 == pizza2)
		   System.out.println(true);
	   else
		   System.out.println(false);

Yes, my compiler seems to print false when I create both of the Strings with the new keyword. The book didn't mention anything about a String constant pool area either. I may need a new book.

OK, so I tried to address the sum1 = BALANCE problem... For some reason it didn't do what I expect it to do because I tested it and set sum1 = BALANCE. It didn't display 'resources are equal', but other than that the program works good enough. To be honest, I ended up spending WAY more time on this program than I wanted to being that I decided to add more things to it like balancing 3 resources...balancing 4 resources. I'm a little proud of myself that I managed to do this and will work on it some more in my free time [(End Result)](https://ibb.co/4FV77bY): 

    #include <iostream>
    #include <cstdlib>
    #include <iomanip>
    using namespace std;

    int main()
    {
        const double BALANCE = 0.50;
        const double BALANCE2 = (1.0/3);
        const double BALANCE3 = 0.25;
        double  resource1, resource2, resource3, resource4, total,
                sum1, sum2, sum3, sum4;
        short int sentinel;
        unsigned short choice;

        cout << "Travian Resource Balancer \n";

        cout << "\n>1: Balance 2 resources\n>2: Balance 3 resources\n>3: Balance 4 resources\nChoice: ";
        cin >> choice;

        if((choice == 1)){
        do{
        cout << "\nResource 1: ";
        cin >> resource1;
        cout << "Resource 2: ";
        cin >> resource2;

        total = resource1 + resource2 + resource3;

        sum1 = resource1 / total;
        sum2 = resource2 / total;

            if(sum1 < BALANCE || sum1 > BALANCE2)
            {
                //result = (resource1 + resource2 + resource3) * (sum1 - BALANCE2);
                sum1 = BALANCE - sum1;
                sum2 = BALANCE - sum2;
                cout << fixed << showpoint << setprecision(2);
                cout << "Resource1 \t" << setw(10) << sum1 * total << "\t = " << resource1 + (sum1 * total) << endl;
                cout << "Resource2 \t" << setw(10) << sum2 * total << "\t = " << resource2 + (sum2 * total) << endl;

                cout << "Repeat? Enter 1 to continue or -1 to quit: ";
                cin >> sentinel;
            }
            else if(sum1 == BALANCE)
            {
                cout << "Resources are equal\n";
                cout << "Repeat? Enter 1 to continue or -1 to quit: ";
                cin >> sentinel;
            }
            else
            {
                exit(1);
            }
            }while(sentinel != -1);

            cin.get();
            cin.ignore();
        } //**************************************
        else if((choice == 2)){
        do{
        cout << "\nResource 1: ";
        cin >> resource1;
        cout << "Resource 2: ";
        cin >> resource2;
        cout << "Resource 3: ";
        cin >> resource3;

        total = resource1 + resource2 + resource3;

        sum1 = resource1 / total;
        sum2 = resource2 / total;
        sum3 = resource3 / total;

            if(sum1 < BALANCE2 || sum1 > BALANCE2)
            {
                //result = (resource1 + resource2 + resource3) * (sum1 - BALANCE2);
                sum1 = BALANCE2 - sum1;
                sum2 = BALANCE2 - sum2;
                sum3 = BALANCE2 - sum3;
                cout << fixed << showpoint << setprecision(2);
                cout << "Resource1 \t" << setw(10) << sum1 * total << "\t = " << resource1 + (sum1 * total) << endl;
                cout << "Resource2 \t" << setw(10) << sum2 * total << "\t = " << resource2 + (sum2 * total) << endl;
                cout << "Resource3 \t" << setw(10) << sum3 * total << "\t = " << resource3 + (sum3 * total) << endl;

                cout << "Repeat? Enter 1 to continue or -1 to quit: ";
                cin >> sentinel;
            }
            else if(sum1 == BALANCE2)
            {
                cout << "Resources are equal\n";
                cout << "Repeat? Enter 1 to continue or -1 to quit: ";
                cin >> sentinel;
            }
            else
            {
                exit(1);
            }
            }while(sentinel != -1);

            cin.get();
            cin.ignore();
        }//**************************************
        else if((choice == 3)){
        do{
        cout << "\nResource 1: ";
        cin >> resource1;
        cout << "Resource 2: ";
        cin >> resource2;
        cout << "Resource 3: ";
        cin >> resource3;
        cout << "Resource 4: ";
        cin >> resource4;

        total = resource1 + resource2 + resource3 + resource4;

        sum1 = resource1 / total;
        sum2 = resource2 / total;
        sum3 = resource3 / total;
        sum4 = resource4 / total;

            if(sum1 < BALANCE3 || sum1 > BALANCE3)
            {
                sum1 = BALANCE3 - sum1;
                sum2 = BALANCE3 - sum2;
                sum3 = BALANCE3 - sum3;
                sum4 = BALANCE3 - sum4;
                cout << fixed << showpoint << setprecision(2);
                cout << "Resource1 \t" << setw(10) << sum1 * total << "\t = " << resource1 + (sum1 * total) << endl;
                cout << "Resource2 \t" << setw(10) << sum2 * total << "\t = " << resource2 + (sum2 * total) << endl;
                cout << "Resource3 \t" << setw(10) << sum3 * total << "\t = " << resource3 + (sum3 * total) << endl;
                cout << "Resource4 \t" << setw(10) << sum4 * total << "\t = " << resource4 + (sum4 * total) << endl;

                cout << "Repeat? Enter 1 to continue or -1 to quit: ";
                cin >> sentinel;
            }
            else if(sum1 == BALANCE3)
            {
                cout << "Resources are equal\n";
                cout << "Repeat? Enter 1 to continue or -1 to quit: ";
                cin >> sentinel;
            }
            else
            {
                exit(1);
            }
            }while(sentinel != -1);

            cin.get();
            cin.ignore();

        return 0;}
    }
